// Package dictionary describes FIX data dictionaries and validates messages
// against them.
//
// Packages generated by fixgen declare their dictionary as Go code, built
// with New: their Dictionary function validates messages without reading
// XML at run time. Package xmldict reads a dictionary from QuickFIX XML.
package dictionary

import (
	"maps"
	"slices"

	fix2 "github.com/sylr/fix2"
)

// ---------------------------------------------------------------------------
// Exported types
// ---------------------------------------------------------------------------

// FieldDef describes a field from the <fields> section of a data dictionary.
type FieldDef struct {
	Tag   int
	Name  string
	Type  string
	Enums map[string]string // value -> description; nil if none
}

// FieldRef is a reference to a field within a message, header, or trailer.
type FieldRef struct {
	Tag      int
	Required bool
}

// GroupDef describes a repeating group within a message.
type GroupDef struct {
	CounterTag int    // NUMINGROUP tag (e.g. 78)
	Name       string // field name (e.g. "NoAllocs")
	Required   bool
	DelimTag   int        // first child tag in XML order — instance delimiter (e.g. 79)
	Fields     []FieldRef // child fields in XML order, components expanded, nested groups excluded
	Groups     []GroupDef // nested sub-groups
	// Layout lists an entry's tags in XML order, components expanded: its
	// fields and, where nested groups sit, their counter tags. FIX requires
	// entry fields in this order; Layout[0] is DelimTag.
	Layout []int
}

// MessageDef describes a single FIX message type.
type MessageDef struct {
	Name    string
	MsgType string
	MsgCat  string
	Fields  []FieldRef // flattened (components/groups resolved)
	Groups  []GroupDef // top-level groups in this message
	// Conditions are the required fields of the message's optional
	// components, required only when the component is present.
	Conditions []Condition

	// Compiled for Validate (see compiled.go).
	body         tagTable          // body tags, with their presence slots
	requiredTags []tracked         // tags required unconditionally, in order
	conds        []compiledCond    // tags required only when an optional component is present
	slots        int32             // presence slots, the envelope's included
	specs        []*fix2.GroupSpec // groups whose entries are skipped for top-level presence
}

// Condition records the required fields of an optional component: they must
// be present only when the component is.
type Condition struct {
	Component  string // name of the optional component
	Activation []int  // tags found only in this component: any present means it is
	Required   []int  // tags required when the component is present
}

// Dict is a FIX data dictionary. Validate uses tables New compiles from it:
// changing the exported fields of a Dict afterwards does not change what
// Validate accepts. A Dict is safe for concurrent use by Validate.
type Dict struct {
	Type, Major, Minor string

	Fields   map[int]*FieldDef
	Messages map[string]*MessageDef // keyed by MsgType (e.g. "D")
	Header   []FieldRef
	Trailer  []FieldRef
	// HeaderGroups and TrailerGroups are the repeating groups of the
	// standard header and trailer (e.g. FIXT 1.1 NoHops), which every
	// message carries.
	HeaderGroups  []GroupDef
	TrailerGroups []GroupDef
	// HeaderConditions and TrailerConditions are the required fields of the
	// header's and trailer's optional components.
	HeaderConditions  []Condition
	TrailerConditions []Condition

	// Compiled for Validate (see compiled.go).
	envelope     tagTable // header, trailer and structural tags
	envSlots     int32    // presence slots of the envelope's tracked tags
	headerReq    []tracked
	trailerReq   []tracked
	headerConds  []compiledCond
	trailerConds []compiledCond
	// envelopeSpecs are the specs of the header and trailer groups when they
	// are too many to copy into every message's specs.
	envelopeSpecs []*fix2.GroupSpec
	enums         tagTable // tag -> index in enumChecks
	enumChecks    []enumCheck

	fieldsByName map[string]*FieldDef
}

// FieldByName returns the field definition with the given name, or nil if not found.
func (d *Dict) FieldByName(name string) *FieldDef {
	return d.fieldsByName[name]
}

// New prepares d for Validate and returns it. xmldict.Load calls it; so does
// code fixgen generates, which declares a package's dictionary as a Dict
// literal of its exported fields. d must not be changed afterwards.
func New(d *Dict) *Dict {
	d.fieldsByName = make(map[string]*FieldDef, len(d.Fields))
	for _, tag := range slices.Sorted(maps.Keys(d.Fields)) {
		if fd := d.Fields[tag]; d.fieldsByName[fd.Name] == nil {
			d.fieldsByName[fd.Name] = fd
		}
	}
	d.compile()
	return d
}
